using System.Net;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Text.Json;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Xunit;
namespace AiCare.Tests;[Collection("Postgres regression")]public sealed class ReportingDataGovernanceRegressionTests(PostgresRegressionFactory factory):IClassFixture<PostgresRegressionFactory>{[Fact]public async Task MetricVersionsCatalogueSchedulesExportsAndQualityQueueAreGoverned(){await factory.EnsureClinicalSeedAsync();var managerName=$"data.manager.{Guid.NewGuid():N}";var coordinatorName=$"data.coordinator.{Guid.NewGuid():N}";var workerName=$"data.worker.{Guid.NewGuid():N}";var workerId=Guid.NewGuid();using(var s=factory.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<CareDbContext>();db.CareWorkers.Add(new CareWorker(workerId,"Data Worker","Care","Flexible",0,0,"Valid","Compliant","Local",TenantDefaults.OrganizationId,TenantDefaults.BranchId));db.AppUsers.AddRange(User(managerName,UserRole.CareManager),User(coordinatorName,UserRole.CareCoordinator),User(workerName,UserRole.CareWorker,workerId));await db.SaveChangesAsync();}async Task<HttpClient> Login(string name){var c=factory.CreateClient();var r=await c.PostAsJsonAsync("/api/auth/login",new{userName=name,password="Admin123!",mfaCode=(string?)null});r.EnsureSuccessStatusCode();c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",(await r.Content.ReadFromJsonAsync<Login>())!.Token);return c;}var manager=await Login(managerName);var coordinator=await Login(coordinatorName);var worker=await Login(workerName);await StepUpTestGrants.GrantAsync(factory,manager,"export");await StepUpTestGrants.GrantAsync(factory,coordinator,"export");Assert.Equal(HttpStatusCode.Forbidden,(await worker.GetAsync("/api/phase1/reporting-governance")).StatusCode);
var metric=await manager.PostAsJsonAsync("/api/phase1/reporting-governance/metrics",new{key="completed-visits",name="Completed visits",description="Completed visit count",calculationKey="completed visits",owner="Operations data owner",sourceEntities="Visits",lineage="Visits.Status -> Completed -> count",effectiveFrom=DateTimeOffset.UtcNow,organizationWide=false});Assert.Equal(HttpStatusCode.Created,metric.StatusCode);var metricJson=JsonDocument.Parse(await metric.Content.ReadAsStringAsync()).RootElement;var metricId=metricJson.GetProperty("id").GetGuid();Assert.True(metricJson.GetProperty("version").GetInt64() >= 1);Assert.Equal(HttpStatusCode.OK,(await manager.PostAsync($"/api/phase1/reporting-governance/metrics/{metricId}/approve",null)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await manager.PostAsync($"/api/phase1/reporting-governance/metrics/{metricId}/approve",null)).StatusCode);
var catalogue=await manager.PostAsJsonAsync("/api/phase1/reporting-governance/catalogue",new{name="Monthly operations",category="Operational",description="Approved operational pack",metricKeys=new[]{"completed-visits"},allowedRoles=new[]{"CareManager","Administrator"},fieldProfile="AggregateOnly",organizationWide=false});Assert.Equal(HttpStatusCode.Created,catalogue.StatusCode);var catalogueId=(await catalogue.Content.ReadFromJsonAsync<Created>())!.Id;Assert.Equal(HttpStatusCode.NotFound,(await coordinator.PostAsJsonAsync("/api/phase1/reporting-compliance/report-runs",new{name="Denied governed export",category="Operational",format="CSV",metrics=new[]{"Completed visits"},filters=new Dictionary<string,string>(),reportCatalogueId=catalogueId})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await manager.PostAsJsonAsync($"/api/phase1/reporting-governance/catalogue/{catalogueId}/schedules",new{frequency="Weekly",nextRunAt=DateTimeOffset.UtcNow.AddDays(-1),owner="Reporting lead"})).StatusCode);Assert.Equal(HttpStatusCode.Created,(await manager.PostAsJsonAsync($"/api/phase1/reporting-governance/catalogue/{catalogueId}/schedules",new{frequency="Monthly",nextRunAt=DateTimeOffset.UtcNow.AddDays(1),owner="Reporting lead"})).StatusCode);
var report=await manager.PostAsJsonAsync("/api/phase1/reporting-compliance/report-runs",new{name="Governed export",category="Operational",format="CSV",metrics=new[]{"Completed visits"},filters=new Dictionary<string,string>(),reportCatalogueId=catalogueId});var reportId=(await report.Content.ReadFromJsonAsync<Created>())!.Id;Assert.Equal(HttpStatusCode.BadRequest,(await manager.GetAsync($"/api/phase1/reporting-governance/report-runs/{reportId}/governed.csv?reason=")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await manager.GetAsync($"/api/phase1/reporting-governance/report-runs/{reportId}/governed.csv?reason=Monthly%20governance%20review")).StatusCode);var unbound=await manager.PostAsJsonAsync("/api/phase1/reporting-compliance/report-runs",new{name="Unbound export",category="Operational",format="CSV",metrics=new[]{"Completed visits"},filters=new Dictionary<string,string>()});var unboundId=(await unbound.Content.ReadFromJsonAsync<Created>())!.Id;Assert.Equal(HttpStatusCode.NotFound,(await manager.GetAsync($"/api/phase1/reporting-governance/report-runs/{unboundId}/governed.csv?reason=Must%20be%20bound")).StatusCode);
var qualityId=Guid.NewGuid();using(var s=factory.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<CareDbContext>();await db.Database.ExecuteSqlInterpolatedAsync($"""insert into data_quality_issues(id,organization_id,branch_id,rule_key,entity_type,severity,status,description,owner) values({qualityId},{TenantDefaults.OrganizationId},{TenantDefaults.BranchId},'duplicate-person','ServiceUser','High','Open','Possible duplicate person','Data steward')""");}Assert.Equal(HttpStatusCode.BadRequest,(await manager.PostAsJsonAsync($"/api/phase1/reporting-governance/quality/{qualityId}/resolve",new{resolution=""})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await manager.PostAsJsonAsync($"/api/phase1/reporting-governance/quality/{qualityId}/resolve",new{resolution="Records compared and duplicate ruled out"})).StatusCode);var workspace=await manager.GetStringAsync("/api/phase1/reporting-governance");Assert.Contains("completed-visits",workspace);Assert.Contains("Monthly operations",workspace);Assert.Contains("Resolved",workspace);using var verify=factory.Services.CreateScope();var verifyDb=verify.ServiceProvider.GetRequiredService<CareDbContext>();Assert.True(await verifyDb.AuditEvents.AnyAsync(x=>x.Action=="reporting.governed_export"&&x.EntityId==reportId));}
private static AppUser User(string n,UserRole r,Guid? w=null)=>new(Guid.NewGuid(),n,$"{n}@aicare.local",PasswordHasher.HashPassword("Admin123!"),r,true,TenantDefaults.OrganizationId,TenantDefaults.BranchId,w,null);private sealed record Login(string Token);private sealed record Created(Guid Id);}
